<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import AppModal from '@/components/AppModal.vue'
import { demoMode, request } from '@/services/quality'
interface Guard {id:number;pharmacy_name:string;phone:string|null;address:string|null;starts_at:string;ends_at:string;reason:string|null}
type Draft=Omit<Guard,'id'>
const rows=ref<Guard[]>([]),busy=ref(false),error=ref(''),canWrite=ref(false),modal=ref(false),deleteModal=ref(false),deleteTarget=ref<Guard>(),editing=ref<number>(),search=ref(''),period=ref('all')
const blank=():Draft=>({pharmacy_name:'',phone:'',address:'',starts_at:'',ends_at:'',reason:''})
const draft=ref<Draft>(blank())
const filtered=computed(()=>rows.value.filter(x=>(!search.value||x.pharmacy_name.toLowerCase().includes(search.value.toLowerCase()))&&(period.value==='all'||(period.value==='current'?new Date(x.starts_at)<=new Date()&&new Date(x.ends_at)>new Date():new Date(x.starts_at)>new Date()))))
async function load(){if(demoMode){error.value='Les pharmacies de garde sont une source manuelle : connectez l’interface API pour consulter les déclarations de votre officine.';return}busy.value=true;try{const response=await request<{data:Guard[];can_write:boolean}>('/gardes');rows.value=response.data;canWrite.value=response.can_write;error.value=''}catch(e){error.value=e instanceof Error?e.message:'Chargement impossible.'}finally{busy.value=false}}
function open(row?:Guard){editing.value=row?.id;draft.value=row?{pharmacy_name:row.pharmacy_name,phone:row.phone||'',address:row.address||'',starts_at:row.starts_at.slice(0,16),ends_at:row.ends_at.slice(0,16),reason:row.reason||''}:blank();error.value='';modal.value=true}
async function save(){busy.value=true;error.value='';try{await request(`/gardes${editing.value?`/${editing.value}`:''}`,editing.value?'PUT':'POST',draft.value);modal.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'Enregistrement impossible.'}finally{busy.value=false}}
function remove(row:Guard){deleteTarget.value=row;deleteModal.value=true}
async function confirmRemove(){if(!deleteTarget.value)return;busy.value=true;try{await request(`/gardes/${deleteTarget.value.id}`,'DELETE');deleteModal.value=false;deleteTarget.value=undefined;await load()}catch(e){error.value=e instanceof Error?e.message:'Suppression impossible.'}finally{busy.value=false}}
function current(row:Guard){const now=Date.now();return new Date(row.starts_at).getTime()<=now&&new Date(row.ends_at).getTime()>now}
onMounted(load)
</script>
<template><main class="page-shell"><header class="page-heading"><div><p class="eyebrow">Déclarations manuelles</p><h1>Pharmacies de garde</h1><p>Planning saisi par l’officine. Il ne constitue pas un calendrier officiel.</p></div><button v-if="canWrite" class="primary-button" :disabled="demoMode" @click="open()">Déclarer une garde</button></header><section class="card"><div class="toolbar"><input v-model="search" aria-label="Rechercher une pharmacie" placeholder="Rechercher une pharmacie"><select v-model="period" aria-label="Filtrer par période"><option value="all">Toutes les périodes</option><option value="current">En cours</option><option value="upcoming">À venir</option></select></div><p v-if="error" role="alert">{{ error }}</p><p v-else-if="busy">Chargement…</p><p v-else-if="!filtered.length">Aucune garde déclarée pour cette officine.</p><div v-else class="table-wrap"><table><thead><tr><th>Pharmacie</th><th>Début</th><th>Fin</th><th>Téléphone</th><th>État</th><th v-if="canWrite">Actions</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td>{{ row.pharmacy_name }}<small>{{ row.address }}</small></td><td>{{ new Date(row.starts_at).toLocaleString() }}</td><td>{{ new Date(row.ends_at).toLocaleString() }}</td><td><a v-if="row.phone" :href="`tel:${row.phone}`">{{ row.phone }}</a><span v-else>—</span></td><td>{{ current(row)?'En cours':'Planifiée' }}</td><td v-if="canWrite"><button @click="open(row)">Modifier</button> <button @click="remove(row)">Supprimer</button></td></tr></tbody></table></div></section><AppModal v-model="modal" :title="editing?'Modifier une garde':'Déclarer une garde'" eyebrow="Source manuelle" :busy="busy"><form class="form-grid" @submit.prevent="save"><label>Nom de la pharmacie<input v-model.trim="draft.pharmacy_name" required maxlength="180"></label><label>Téléphone<input v-model.trim="draft.phone" type="tel" maxlength="40"></label><label class="wide">Adresse<input v-model.trim="draft.address" maxlength="255"></label><label>Début<input v-model="draft.starts_at" type="datetime-local" required></label><label>Fin<input v-model="draft.ends_at" type="datetime-local" required></label><label class="wide">Motif / source de la déclaration<textarea v-model.trim="draft.reason" maxlength="500" rows="2" placeholder="Facultatif"></textarea></label><p v-if="error" class="wide" role="alert">{{ error }}</p><footer class="modal-footer wide"><button type="button" :disabled="busy" @click="modal=false">Annuler</button><button class="primary-button" type="submit" :disabled="busy">Enregistrer</button></footer></form></AppModal><AppModal v-model="deleteModal" title="Supprimer cette garde ?" :busy="busy"><p class="form-grid">La déclaration de {{ deleteTarget?.pharmacy_name }} sera supprimée.</p><footer class="modal-footer"><button :disabled="busy" @click="deleteModal=false">Annuler</button><button class="primary-button" :disabled="busy" @click="confirmRemove">Confirmer la suppression</button></footer></AppModal></main></template>
<style scoped>.page-shell{padding:2rem;max-width:1200px;margin:auto}.page-heading,.toolbar{display:flex;justify-content:space-between;align-items:center;gap:1rem}.card{margin-top:1.5rem;padding:1.25rem;background:white;border:1px solid #e2e8f0;border-radius:1rem}.toolbar{margin-bottom:1rem}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.8rem;border-bottom:1px solid #e2e8f0}small{display:block;color:#64748b}a{color:#0369a1}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;padding:1rem}.form-grid label{display:grid;gap:.4rem}.form-grid input,.form-grid textarea,.toolbar input,.toolbar select{padding:.65rem;border:1px solid #cbd5e1;border-radius:.5rem}.wide{grid-column:1/-1}.modal-footer{display:flex;justify-content:flex-end;gap:.75rem}@media(max-width:700px){.page-shell{padding:1rem}.page-heading{align-items:flex-start;flex-direction:column}.table-wrap{overflow:auto}.form-grid{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
